1	// Package calibrate 是本地器具校准与证书的本地台账。
2	//
3	// 台账只保存在本机指定文件中，不连接任何真实实验室。多次打开同一文件
4	// 可以继续查询与操作，不同文件之间的数据互不相干。
5	package calibrate
6	
7	import (
8		"encoding/json"
9		"errors"
10		"fmt"
11		"math"
12		"os"
13		"path/filepath"
14		"sort"
15		"strings"
16		"time"
17	)
18	
19	// 日期布局，所有入参日期都必须是实际存在的 YYYY-MM-DD。
20	const DateLayout = "2006-01-02"
21	
22	// Status 是器具的运行状态。
23	type Status string
24	
25	const (
26		// StatusPending 表示待校准，新登记器具的初始状态。
27		StatusPending Status = "待校准"
28		// StatusInUse 表示在用；在用本身不代表已经校准。
29		StatusInUse Status = "在用"
30		// StatusRetired 表示停用；停用不删除证书与使用记录。
31		StatusRetired Status = "停用"
32	)
33	
34	// ParseStatus 把命令行或文件中的状态文本解析为 Status。
35	func ParseStatus(s string) (Status, error) {
36		switch strings.TrimSpace(s) {
37		case string(StatusPending), "pending":
38			return StatusPending, nil
39		case string(StatusInUse), "in-use", "in_use":
40			return StatusInUse, nil
41		case string(StatusRetired), "retired":
42			return StatusRetired, nil
43		default:
44			return "", fmt.Errorf("无效状态 %q：只能是 在用、停用 或 待校准", s)
45		}
46	}
47	
48	// Instrument 是登记的器具信息。
49	type Instrument struct {
50		ID           string  `json:"id"`
51		Name         string  `json:"name"`
52		AllowedError float64 `json:"allowed_error"`
53		Status       Status  `json:"status"`
54		RegisteredAt string  `json:"registered_at"`
55	}
56	
57	// Certificate 是一张校准证书。
58	type Certificate struct {
59		Number       string  `json:"number"`
60		InstrumentID string  `json:"instrument_id"`
61		CalDate      string  `json:"cal_date"`
62		Expiry       string  `json:"expiry"`
63		Method       string  `json:"method"`
64		Error        float64 `json:"error"`
65		Summary      string  `json:"summary"`
66		CreatedAt    string  `json:"created_at"`
67	}
68	
69	// Pass 按证书自身数据判断是否合格：测得误差绝对值不超过允许误差（含限值）。
70	// 结论由数据计算，录入者不能自行选择。
71	func (c Certificate) Pass(allowedError float64) bool {
72		return math.Abs(c.Error) <= allowedError
73	}
74	
75	// UsageRecord 是一次使用申请的留痕，原因在申请发生时冻结。
76	type UsageRecord struct {
77		InstrumentID string   `json:"instrument_id"`
78		RequestedAt  string   `json:"requested_at"`
79		Allowed      bool     `json:"allowed"`
80		Reasons      []string `json:"reasons"`
81	}
82	
83	// ledgerData 是台账文件的持久化结构。
84	type ledgerData struct {
85		Version      int           `json:"version"`
86		Instruments  []Instrument  `json:"instruments"`
87		Certificates []Certificate `json:"certificates"`
88		Usage        []UsageRecord `json:"usage"`
89		Plans        []Plan        `json:"plans,omitempty"`
90	}
91	
92	// Ledger 是一份可操作的本地台账。
93	type Ledger struct {
94		path string
95		now  func() time.Time
96		data ledgerData
97	}
98	
99	// ValidationError 表示输入未通过业务校验，调用方不会改动任何已有记录。
100	type ValidationError struct{ Msg string }
101	
102	func (e *ValidationError) Error() string { return e.Msg }
103	
104	func validationError(format string, args ...any) error {
105		return &ValidationError{Msg: fmt.Sprintf(format, args...)}
106	}
107	
108	// IsValidation 报告 err 是否为业务校验错误。
109	func IsValidation(err error) bool {
110		var v *ValidationError
111		return errors.As(err, &v)
112	}
113	
114	// ConflictError 表示同号证书内容不一致等冲突，已有数据保持不变。
115	type ConflictError struct{ Msg string }
116	
117	func (e *ConflictError) Error() string { return e.Msg }
118	
119	// IsConflict 报告 err 是否为冲突错误。
120	func IsConflict(err error) bool {
121		var c *ConflictError
122		return errors.As(err, &c)
123	}
124	
125	// ErrNotFound 表示编号在台账中不存在。
126	var ErrNotFound = errors.New("记录不存在")
127	
128	func cleanText(s string) (string, error) {
129		t := strings.TrimSpace(s)
130		if t == "" {
131			return "", validationError("不能留空或只有空白")
132		}
133		return t, nil
134	}
135	
136	func parseFiniteDate(s, field string) (time.Time, string, error) {
137		t := strings.TrimSpace(s)
138		if t == "" {
139			return time.Time{}, "", validationError("%s不能留空", field)
140		}
141		parsed, err := time.Parse(DateLayout, t)
142		if err != nil {
143			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
144		}
145		// time.Parse 对 YYYY-MM-DD 遇到超范围日期会直接报错；再用 Format
146		// 往返一次，拒绝 2024-2-3 之类格式不符的输入。
147		if parsed.Format(DateLayout) != t {
148			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
149		}
150		return parsed, t, nil
151	}
152	
153	func finiteNumber(v float64, field string) error {
154		if math.IsNaN(v) || math.IsInf(v, 0) {
155			return validationError("%s必须是有限数", field)
156		}
157		return nil
158	}
159	
160	// Open 打开 path 所指的本机台账；文件不存在时建立一份新台账。
161	// 同一文件可以反复打开继续操作，不同 path 的数据互不混入。
162	func Open(path string) (*Ledger, error) {
163		return openAt(path, time.Now)
164	}
165	
166	func openAt(path string, now func() time.Time) (*Ledger, error) {
167		if strings.TrimSpace(path) == "" {
168			return nil, fmt.Errorf("台账文件路径不能为空")
169		}
170		l := &Ledger{
171			path: path,
172			now:  now,
173			data: ledgerData{Version: 1},
174		}
175		raw, err := os.ReadFile(path)
176		if err != nil {
177			if errors.Is(err, os.ErrNotExist) {
178				return l, nil
179			}
180			return nil, fmt.Errorf("读取台账 %s: %w", path, err)
181		}
182		if len(raw) > 0 {
183			if err := json.Unmarshal(raw, &l.data); err != nil {
184				return nil, fmt.Errorf("台账文件 %s 已损坏: %w", path, err)
185			}
186		}
187		if l.data.Version == 0 {
188			l.data.Version = 1
189		}
190		return l, nil
191	}
192	
193	// Path 返回台账文件位置。
194	func (l *Ledger) Path() string { return l.path }
195	
196	// save 把当前台账完整写回文件：先写临时文件再原子改名，
197	// 保证无效录入中断时不会留下半份记录。
198	func (l *Ledger) save() error {
199		if err := os.MkdirAll(filepath.Dir(l.path), 0o755); err != nil {
200			return fmt.Errorf("写入台账文件 %s 前创建目录失败: %w", l.path, err)
201		}
202		raw, err := json.MarshalIndent(l.data, "", "  ")
203		if err != nil {
204			return fmt.Errorf("序列化台账 %s: %w", l.path, err)
205		}
206		raw = append(raw, '\n')
207		tmp, err := os.CreateTemp(filepath.Dir(l.path), ".ledger-*.tmp")
208		if err != nil {
209			return fmt.Errorf("为台账 %s 创建临时文件: %w", l.path, err)
210		}
211		tmpName := tmp.Name()
212		defer os.Remove(tmpName)
213		if _, err := tmp.Write(raw); err != nil {
214			tmp.Close()
215			return fmt.Errorf("写入台账 %s 的临时文件: %w", l.path, err)
216		}
217		if err := tmp.Close(); err != nil {
218			return fmt.Errorf("关闭台账 %s 的临时文件: %w", l.path, err)
219		}
220		if err := os.Rename(tmpName, l.path); err != nil {
221			return fmt.Errorf("替换台账文件 %s: %w", l.path, err)
222		}
223		return nil
224	}
225	
226	func (l *Ledger) findInstrument(id string) *Instrument {
227		for i := range l.data.Instruments {
228			if l.data.Instruments[i].ID == id {
229				return &l.data.Instruments[i]
230			}
231		}
232		return nil
233	}
234	
235	func (l *Ledger) findCertificate(number string) *Certificate {
236		for i := range l.data.Certificates {
237			if l.data.Certificates[i].Number == number {
238				return &l.data.Certificates[i]
239			}
240		}
241		return nil
242	}
243	
244	// RegisterInput 是登记器具的输入。
245	type RegisterInput struct {
246		ID           string
247		Name         string
248		AllowedError float64
249	}
250	
251	// Register 登记一件新器具。编号、名称不得为空白，允许误差必须是不小于零的
252	// 有限数；编号重复或输入无效时明确拒绝，原记录不变。新器具处于待校准状态。
253	//
254	// 只有本次保存成功，新器具才算正式登记：若台账文件无法写入或替换，明确返回
255	// 保存错误而不返回已登记的器具，台账（含同一对象随后的列出、按编号核对、
256	// 编号占用判断以及校准与使用安排）与登记前完全一致——失败的器具不出现在列表、
257	// 不占用编号，也不会在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次
258	// 提交同号合法内容仍报保存错误（不会因内存里残留的失败器具而被当成编号重复）。
259	// 恢复可写后无需重新打开台账，重新提交且保存成功才新增一件待校准器具，
260	// 登记时间、名称与允许误差均取本次成功提交的内容，不沿用失败申请；成功后
261	// 再登记同号仍按编号唯一拒绝。未通过业务校验的申请仍按原有方式拒绝，
262	// 不会因台账不可写而被混成保存失败。
263	func (l *Ledger) Register(in RegisterInput) (*Instrument, error) {
264		id, err := cleanText(in.ID)
265		if err != nil {
266			return nil, fmt.Errorf("器具编号无效：%w", err)
267		}
268		name, err := cleanText(in.Name)
269		if err != nil {
270			return nil, fmt.Errorf("器具名称无效：%w", err)
271		}
272		if err := finiteNumber(in.AllowedError, "允许的绝对误差"); err != nil {
273			return nil, err
274		}
275		if in.AllowedError < 0 {
276			return nil, validationError("允许的绝对误差不能小于零")
277		}
278		if l.findInstrument(id) != nil {
279			return nil, validationError("器具编号 %s 已存在，编号必须唯一", id)
280		}
281		inst := Instrument{
282			ID:           id,
283			Name:         name,
284			AllowedError: in.AllowedError,
285			Status:       StatusPending,
286			RegisteredAt: l.now().Format(time.RFC3339),
287		}
288		// 在独立的新切片上暂存新器具：只有原子替换台账文件成功后才提交。
289		// 写盘失败时恢复原切片，保证同一台账对象随后的列出、按编号核对与编号
290		// 占用判断都与登记前一致，失败器具也不会被之后的写盘顺带写入。
291		original := l.data.Instruments
292		staged := make([]Instrument, 0, len(original)+1)
293		staged = append(staged, original...)
294		staged = append(staged, inst)
295		l.data.Instruments = staged
296		if err := l.save(); err != nil {
297			l.data.Instruments = original
298			return nil, err
299		}
300		// 返回已保存器具的独立副本：返回结果只表示本次保存成功的内容。
301		saved := *l.findInstrument(id)
302		return &saved, nil
303	}
304	
305	// SetStatus 切换器具状态。切换为在用不代表已校准；停用不删除证书与使用记录。
306	//
307	// 目标状态合法且与最后成功保存的状态不同后才写盘：若台账文件无法写入或替换，
308	// 明确返回保存错误，台账（含同一对象随后的列出、按器具核对、待办与使用判断）
309	// 与切换前完全一致——器具仍保持最后成功保存的状态，失败的目标状态既不会提前
310	// 参与使用资格判断，也不会在此后其他成功操作写盘时被顺带写入；文件仍不可写时
311	// 再次提交同一目标状态仍报保存错误（不会因内存已被改成目标状态而被当成
312	// “状态未变”跳过保存返回成功）。恢复可写后无需重新打开台账，重新提交且保存
313	// 成功，新状态才生效。请求状态本来就等于最后成功保存的状态时直接成功，不写盘。
314	func (l *Ledger) SetStatus(id string, status Status) error {
315		switch status {
316		case StatusInUse, StatusRetired, StatusPending:
317		default:
318			return validationError("无效状态：只能是 在用、停用 或 待校准")
319		}
320		inst := l.findInstrument(id)
321		if inst == nil {
322			return fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
323		}
324		if inst.Status == status {
325			return nil
326		}
327		// 在整份器具切片的独立副本上暂存新状态：只有原子替换台账文件成功后才
328		// 提交。写盘失败时恢复原切片，保证同一台账对象随后看到的器具状态、列出
329		// 结果、待办与使用判断都与切换前一致；再次提交相同状态仍会走到保存，
330		// 失败状态也不会被之后的写盘顺带写入。
331		original := l.data.Instruments
332		staged := make([]Instrument, len(original))
333		copy(staged, original)
334		for i := range staged {
335			if staged[i].ID == id {
336				staged[i].Status = status
337				break
338			}
339		}
340		l.data.Instruments = staged
341		if err := l.save(); err != nil {
342			l.data.Instruments = original
343			return err
344		}
345		return nil
346	}
347	
348	// CertificateInput 是录入校准证书的输入。
349	type CertificateInput struct {
350		InstrumentID string
351		Number       string
352		CalDate      string
353		Expiry       string
354		Method       string
355		Error        float64
356		Summary      string
357	}
358	
359	// AddCertificate 录入一张校准证书并返回它；若同号证书且全部业务字段一致，
360	// 返回原证书且不增加历史（幂等）。同号内容不同报冲突且不改动已有数据。
361	//
362	// 返回的证书只是本次已保存内容的展示副本，与台账内存储不共享内存：调用方
363	// 整理返回结果中的误差、截止日、编号或其他字段，不会改写台账里的正式证书，
364	// 不影响最近证书的选择、使用资格判断与编号占用，也不会被此后的写盘带入文件；
365	// 重新查询得到的仍是实际保存的内容。
366	//
367	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
368	// 台账（含同一对象随后的查询）与录入前完全一致——失败的证书既不进入历史、
369	// 不占用证书编号或该器具当天的位置，也不会在此后其他成功操作写盘时被顺带写入；
370	// 恢复可写后重新提交同号同内容会作为新证书正常录入。
371	func (l *Ledger) AddCertificate(in CertificateInput) (*Certificate, bool, error) {
372		instID, err := cleanText(in.InstrumentID)
373		if err != nil {
374			return nil, false, fmt.Errorf("器具编号无效：%w", err)
375		}
376		number, err := cleanText(in.Number)
377		if err != nil {
378			return nil, false, fmt.Errorf("证书编号无效：%w", err)
379		}
380		method, err := cleanText(in.Method)
381		if err != nil {
382			return nil, false, fmt.Errorf("校准方法无效：%w", err)
383		}
384		summary, err := cleanText(in.Summary)
385		if err != nil {
386			return nil, false, fmt.Errorf("摘要无效：%w", err)
387		}
388		if err := finiteNumber(in.Error, "测得误差"); err != nil {
389			return nil, false, err
390		}
391	
392		inst := l.findInstrument(instID)
393		if inst == nil {
394			return nil, false, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
395		}
396	
397		_, calText, err := parseFiniteDate(in.CalDate, "校准日期")
398		if err != nil {
399			return nil, false, err
400		}
401		_, expText, err := parseFiniteDate(in.Expiry, "有效期截止日")
402		if err != nil {
403			return nil, false, err
404		}
405		// 与“本机今天”按日历日期比较，避免时分秒和时区造成边界误差。
406		todayText := l.now().Format(DateLayout)
407		if calText > todayText {
408			return nil, false, validationError("校准日期 %s 不能晚于本机今天 %s", calText, todayText)
409		}
410		if expText <= calText {
411			return nil, false, validationError("有效期截止日 %s 必须晚于校准日期 %s", expText, calText)
412		}
413	
414		if existing := l.findCertificate(number); existing != nil {
415			same := existing.InstrumentID == instID &&
416				existing.CalDate == calText &&
417				existing.Expiry == expText &&
418				existing.Method == method &&
419				existing.Summary == summary &&
420				existing.Error == in.Error
421			if !same {
422				return nil, false, &ConflictError{Msg: fmt.Sprintf(
423					"证书编号 %s 已存在且内容不同，拒绝覆盖已有数据", number)}
424			}
425			// 同号且全部业务字段一致：返回原证书，不增加历史记录。
426			// 返回独立副本：调用方对返回结果的整理不能成为改写正式证书的途径。
427			dup := *existing
428			return &dup, true, nil
429		}
430	
431		// 同一器具同一天不接受两张不同编号的证书。
432		for i := range l.data.Certificates {
433			c := &l.data.Certificates[i]
434			if c.InstrumentID == instID && c.CalDate == calText {
435				return nil, false, validationError(
436					"器具 %s 在 %s 已有证书 %s，同一天不能再登记不同编号的证书",
437					instID, calText, c.Number)
438			}
439		}
440	
441		cert := Certificate{
442			Number:       number,
443			InstrumentID: instID,
444			CalDate:      calText,
445			Expiry:       expText,
446			Method:       method,
447			Error:        in.Error,
448			Summary:      summary,
449			CreatedAt:    l.now().Format(time.RFC3339),
450		}
451		// 在独立的新切片上暂存新证书：只有原子替换台账文件成功后才提交。
452		// 写盘失败时恢复原切片，保证同一台账对象随后看到的历史、最近证书、
453		// 证书编号占用与同日位置都与录入前一致，且不会被之后的写盘顺带写入。
454		original := l.data.Certificates
455		staged := make([]Certificate, 0, len(original)+1)
456		staged = append(staged, original...)
457		staged = append(staged, cert)
458		l.data.Certificates = staged
459		if err := l.save(); err != nil {
460			l.data.Certificates = original
461			return nil, false, err
462		}
463		// 返回已保存证书的独立副本：返回结果只表示本次保存的内容，调用方的
464		// 后续整理不会连带改写台账内的正式证书。
465		saved := *l.findCertificate(number)
466		return &saved, false, nil
467	}
468	
469	// certificatesOf 返回某器具的证书，按校准日期从新到旧排序；日期相同时
470	// （实际业务不会允许同日多证）以证书编号排序保证结果稳定。
471	func (l *Ledger) certificatesOf(id string) []Certificate {
472		var out []Certificate
473		for _, c := range l.data.Certificates {
474			if c.InstrumentID == id {
475				out = append(out, c)
476			}
477		}
478		sort.Slice(out, func(i, j int) bool {
479			if out[i].CalDate != out[j].CalDate {
480				return out[i].CalDate > out[j].CalDate
481			}
482			return out[i].Number < out[j].Number
483		})
484		return out
485	}
486	
487	// LatestCertificate 返回器具按校准日期确定的最近证书；没有证书时返回 nil。
488	// 最近证书与录入先后无关，补录较早证书只增加历史。
489	func (l *Ledger) LatestCertificate(id string) *Certificate {
490		cs := l.certificatesOf(id)
491		if len(cs) == 0 {
492			return nil
493		}
494		return &cs[0]
495	}
496	
497	// CertificateView 是证书及其在当前日期下的判定结果。
498	type CertificateView struct {
499		Certificate
500		Pass    bool `json:"pass"`
501		Expired bool `json:"expired"`
502	}
503	
504	func viewCertificate(c Certificate, allowed float64, today time.Time) CertificateView {
505		return CertificateView{
506			Certificate: c,
507			Pass:        c.Pass(allowed),
508			// 有效期截止日当天起即到期：按日历日期比较，今天 >= 截止日即为到期。
509			Expired: today.Format(DateLayout) >= c.Expiry,
510		}
511	}
512	
513	// UsageDecision 是一次使用申请的评估结果，原因在申请时冻结留痕。
514	type UsageDecision struct {
515		InstrumentID string
516		Allowed      bool
517		Reasons      []string
518		Latest       *CertificateView
519		evaluatedAt  time.Time
520	}
521	
522	// evaluateAt 按器具状态与“最近证书”判定 now 所在本机日历日期能否使用，
523	// 并列出全部适用原因。最近证书超差或到期时不会回退到更早的合格证书。
524	// 同一次核对的各部分必须共用同一个 now，避免跨午夜时判断不一致。
525	func (l *Ledger) evaluateAt(id string, now time.Time) (*Instrument, *UsageDecision) {
526		today := now
527		inst := l.findInstrument(id)
528		if inst == nil {
529			return nil, nil
530		}
531		d := &UsageDecision{InstrumentID: id, evaluatedAt: today}
532		if inst.Status != StatusInUse {
533			d.Reasons = append(d.Reasons, fmt.Sprintf("器具当前状态为%s，只有在用器具可以申请使用", inst.Status))
534		}
535		latest := l.LatestCertificate(id)
536		if latest == nil {
537			d.Reasons = append(d.Reasons, "没有校准证书")
538		} else {
539			v := viewCertificate(*latest, inst.AllowedError, today)
540			d.Latest = &v
541			if !v.Pass {
542				d.Reasons = append(d.Reasons, fmt.Sprintf(
543					"最近证书 %s 测得误差绝对值 %g 超过允许误差 %g，判定超差",
544					latest.Number, math.Abs(latest.Error), inst.AllowedError))
545			}
546			if v.Expired {
547				d.Reasons = append(d.Reasons, fmt.Sprintf("最近证书 %s 已于 %s 到期（截止日当天即到期）",
548					latest.Number, latest.Expiry))
549			}
550		}
551		d.Allowed = len(d.Reasons) == 0
552		return inst, d
553	}
554	
555	// CanUse 只按当前数据评估能否使用，不留存申请记录。
556	func (l *Ledger) CanUse(id string) (*UsageDecision, error) {
557		inst, d := l.evaluateAt(id, l.now())
558		if inst == nil {
559			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
560		}
561		return d, nil
562	}
563	
564	// cloneReasons 返回原因切片的独立副本，使对外返回的数据与台账内部存储
565	// 不共享底层数组：调用方替换、删减或补充返回结果中的原因，不会改写
566	// 已留痕的历史原因。nil 保持 nil，以维持空结果的既有表现。
567	func cloneReasons(in []string) []string {
568		if in == nil {
569			return nil
570		}
571		return append([]string(nil), in...)
572	}
573	
574	// RequestUse 针对已有器具提交使用申请：无论允许或拒绝都保存申请时间、结果
575	// 与当时全部原因。未知编号报错且不新增记录。
576	//
577	// 只有本次记录保存成功，申请才算提交完成：若台账文件无法写入或替换，明确返回
578	// 保存错误而不返回评估结果，台账（含同一对象随后的全部使用记录与按器具核对中
579	// 的被拒绝记录）与申请前完全一致——本次申请的时间、允许结果与拒绝原因不进入
580	// 历史，也不会在此后其他成功操作写盘时被顺带写入；器具登记信息、证书与校准计划
581	// 不因这次失败发生变化。恢复可写后无需重新打开台账，在同一台账重新申请才会按
582	// 当时的器具状态与证书重新判断并新增一条记录。
583	func (l *Ledger) RequestUse(id string) (*UsageDecision, error) {
584		if strings.TrimSpace(id) == "" {
585			return nil, fmt.Errorf("器具编号无效：%w", validationError("不能留空或只有空白"))
586		}
587		inst, d := l.evaluateAt(id, l.now())
588		if inst == nil {
589			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
590		}
591		// 留痕使用独立副本：返回给调用方的 d.Reasons 与其后的整理操作
592		// 不能成为改写台账内历史原因的途径。
593		rec := UsageRecord{
594			InstrumentID: id,
595			RequestedAt:  d.evaluatedAt.Format(time.RFC3339),
596			Allowed:      d.Allowed,
597			Reasons:      cloneReasons(d.Reasons),
598		}
599		if rec.Reasons == nil {
600			rec.Reasons = []string{}
601		}
602		// 在独立的新切片上暂存本次申请：只有原子替换台账文件成功后才提交。
603		// 写盘失败时恢复原切片，保证同一台账对象随后看到的全部使用记录与
604		// 按器具核对中的被拒绝记录都与申请前一致，失败申请也不会被之后的
605		// 写盘顺带写入。
606		original := l.data.Usage
607		staged := make([]UsageRecord, 0, len(original)+1)
608		staged = append(staged, original...)
609		staged = append(staged, rec)
610		l.data.Usage = staged
611		if err := l.save(); err != nil {
612			l.data.Usage = original
613			return nil, err
614		}
615		return d, nil
616	}
617	
618	// InstrumentReview 是按器具核对的完整视图。
619	type InstrumentReview struct {
620		Instrument Instrument        `json:"instrument"`
621		CanUse     bool              `json:"can_use"`
622		Reasons    []string          `json:"reasons"`
623		Latest     *CertificateView  `json:"latest"`
624		History    []CertificateView `json:"history"`
625		Rejections []UsageRecord     `json:"rejections"`
626		Plans      []PlanView        `json:"plans"`
627	}
628	
629	// Review 按器具核对：登记信息、当前能否使用及原因、最近证书与到期日、
630	// 全部历史证书、被拒绝的使用记录以及该器具当前与已结束的校准计划。
631	// 整份核对只采用核对开始时的一次本机日期：即使查询结束前跨过午夜，
632	// 能否使用、最近证书、历史证书到期判断与未结束计划标记也不会各自变成新一天。
633	// 历史拒绝原因按申请当时的冻结内容展示，不随本次采用的日期重新计算。
634	// 返回的证书、拒绝记录与计划（含改期历史）都是独立展示副本，调用方的
635	// 整理不回写台账，也不影响此前或之后分别取得的其他结果。
636	func (l *Ledger) Review(id string) (*InstrumentReview, error) {
637		// 本次核对只在开始时取一次本机时间，整份结果共用，跨午夜不分裂判断；
638		// 下一次核对会重新取当时的本机日期，不沿用本次结果。
639		now := l.now()
640		inst, d := l.evaluateAt(id, now)
641		if inst == nil {
642			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
643		}
644		r := &InstrumentReview{
645			Instrument: *inst,
646			CanUse:     d.Allowed,
647			Reasons:    d.Reasons,
648			Latest:     d.Latest,
649		}
650		if r.Reasons == nil {
651			r.Reasons = []string{}
652		}
653		today := now
654		for _, c := range l.certificatesOf(id) {
655			r.History = append(r.History, viewCertificate(c, inst.AllowedError, today))
656		}
657		for _, u := range l.data.Usage {
658			if u.InstrumentID == id && !u.Allowed {
659				// 逐条深拷贝原因：对外核对视图中的历史拒绝记录只是展示副本，
660				// 调用方的整理不能回写台账，也不能影响其他入口已取得的结果。
661				u.Reasons = cloneReasons(u.Reasons)
662				r.Rejections = append(r.Rejections, u)
663			}
664		}
665		r.Plans = l.planViews(id, today)
666		return r, nil
667	}
668	
669	// Instruments 返回全部登记器具的副本，按编号排序。
670	func (l *Ledger) Instruments() []Instrument {
671		out := append([]Instrument(nil), l.data.Instruments...)
672		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
673		return out
674	}
675	
676	// UsageRecords 返回全部使用申请记录，按申请时间排序。
677	// 返回的是展示副本：整理其中原因不会改动台账内已冻结的留痕，
678	// 也不会被后续正常写盘带入文件。
679	func (l *Ledger) UsageRecords() []UsageRecord {
680		out := append([]UsageRecord(nil), l.data.Usage...)
681		for i := range out {
682			out[i].Reasons = cloneReasons(out[i].Reasons)
683		}
684		sort.SliceStable(out, func(i, j int) bool {
685			if out[i].RequestedAt != out[j].RequestedAt {
686				return out[i].RequestedAt < out[j].RequestedAt
687			}
688			return out[i].InstrumentID < out[j].InstrumentID
689		})
690		return out
691	}
692

