530		if p == nil || p.PlannedDate != "2026-10-20" || p.OriginalDate != "2026-10-10" {
531			t.Fatalf("重开后计划丢失：%+v", p)
532		}
533		if len(p.Changes) != 1 || p.Changes[0].Reason != "改期留痕" {
534			t.Fatalf("重开后改期历史丢失：%+v", p)
