539			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
540		})
541		if _, _, err := reopened.CompletePlan("P-1", "C-1"); err != nil {
542			t.Fatalf("重开后应能继续完成计划：%v", err)
543		}
544	
545		// 旧台账文件（没有 plans 字段）按无计划处理，且可以正常新增计划。
546		oldPath := filepath.Join(dir, "old.json")
547		oldRaw, _ := json.Marshal(map[string]any{
548			"version": 1,
549			"instruments": []Instrument{{
550				ID: "OLD-1", Name: "老表", AllowedError: 0.5,
551				Status: StatusPending, RegisteredAt: "2026-09-01T00:00:00Z",
552			}},
553			"certificates": []Certificate{},
554			"usage":        []UsageRecord{},
555		})
556		if err := os.WriteFile(oldPath, oldRaw, 0o644); err != nil {
557			t.Fatalf("write old ledger: %v", err)
558		}
559		oldLedger, err := openAt(oldPath, clock)
560		if err != nil {
561			t.Fatalf("open old: %v", err)
562		}
563		items, err := oldLedger.Todos("")
564		if err != nil || len(items) != 0 {
565			t.Fatalf("旧台账应按无计划处理，items=%+v err=%v", items, err)
566		}
567		plans, err := oldLedger.Plans("OLD-1")
568		if err != nil || len(plans) != 0 {
569			t.Fatalf("旧台账器具应无计划，plans=%+v err=%v", plans, err)
570		}
571		if _, err := oldLedger.CreatePlan(PlanInput{
572			Number: "P-OLD-1", InstrumentID: "OLD-1", Date: "2026-10-10", Note: "补建",
573		}); err != nil {
574			t.Fatalf("旧台账应能新增计划：%v", err)
575		}
576	}
