303		cert := func(path string, number, cal, expiry, summary string) result {
304			return runArgs(t, "cert", "-f", path,
305				"--instrument", "DUP", "--number", number,
306				"--cal-date", cal, "--expiry", expiry,
307				"--method", "JJF", "--error", "0.1", "--summary", summary)
308		}
309		if r := cert(a, "C-1", "2020-09-01", "2030-09-01", "首次"); r.code != 0 {
310			t.Fatalf("a 录入证书失败: %s", r.stderr)
311		}
312		if r := cert(b, "C-1", "2020-09-02", "2030-09-02", "另一份"); r.code != 0 {
313			t.Fatalf("b 录入同号证书应独立通过: %s", r.stderr)
314		}
315		// 同号内容不同只在 a 内冲突。
316		if r := cert(a, "C-1", "2020-09-03", "2030-09-03", "冲突内容"); r.code != 1 {
317			t.Fatalf("a 中同号内容不同应冲突退出 1，得到 %d", r.code)
318		}
319		if r := cert(b, "C-1", "2020-09-02", "2030-09-02", "另一份"); r.code != 0 {
320			t.Fatalf("b 的幂等证书不应受 a 影响，code=%d stderr=%s", r.code, r.stderr)
321		}
322	
323		plan := func(path string) result {
324			return runArgs(t, "plan", "-f", path,
325				"--instrument", "DUP", "--number", "PL-1",
326				"--date", "2030-10-20", "--note", "计划")
327		}
328		if r := plan(a); r.code != 0 {
329			t.Fatalf("a 建计划失败: %s", r.stderr)
330		}
331		if r := plan(b); r.code != 0 {
332			t.Fatalf("b 使用同号计划应独立通过: %s", r.stderr)
333		}
334		if r := plan(a); r.code != 1 {
335			t.Fatalf("a 中重复计划号应被拒，得到 %d", r.code)
336		}
337	
338		// 查询“最近证书”只看目标文件：a、b 的 C-1 校准日期不同。
339		ra := runArgs(t, "review", "--id", "DUP", "-f", a, "--json")
340		rb := runArgs(t, "review", "--id", "DUP", "-f", b, "--json")
341		if ra.code != 0 || rb.code != 0 {
342			t.Fatalf("review 失败 %d/%d", ra.code, rb.code)
343		}
344		var va, vb struct {
345			Latest struct {
346				CalDate string `json:"cal_date"`
347			} `json:"latest"`
348		}
349		if err := json.Unmarshal([]byte(ra.stdout), &va); err != nil {
