// TestHistoricalCertCannotCompleteTwoPlans 历史证书已用于完成一项计划后，
// 不能再用于完成同一器具的另一项计划，第二项计划保持未完成并留在待办。
func TestHistoricalCertCannotCompleteTwoPlans(t *testing.T) {
	l := setupHistoricalBackfillLedger(t)
	mustAddCert(t, l, CertificateInput{
		InstrumentID: "M-1", Number: "C-NEW", CalDate: histNewerCal,
		Expiry: histNewerExp, Method: "规范A", Error: 0.8, Summary: "较新超差",
	})
	mustAddCert(t, l, CertificateInput{
		InstrumentID: "M-1", Number: "C-OLD", CalDate: histOlderCal,
		Expiry: histOlderExp, Method: "规范A", Error: 0.1, Summary: "较早合格",
	})
	if _, _, err := l.CompletePlan("P-1", "C-OLD"); err != nil {
		t.Fatalf("complete P-1: %v", err)
	}

	// P-1 已结束，同器具可以建立新计划；但同一张历史证书不能再用一次。
	mustPlan(t, l, PlanInput{
		Number: "P-2", InstrumentID: "M-1", Date: "2026-11-10", Note: "下一轮",
	})
	_, _, err := l.CompletePlan("P-2", "C-OLD")
	if !IsValidation(err) || !strings.Contains(err.Error(), "已用于完成计划") {
		t.Fatalf("已用于完成其他计划的证书应被拒绝，得到 %v", err)
	}
	p2 := l.findPlan("P-2")
	if p2.Status != PlanStatusOpen || p2.CompletedAt != "" || p2.CertificateNumber != "" {
		t.Fatalf("复用被拒后第二项计划不应写入完成信息：%+v", p2)
	}
	items, _ := l.Todos("")
	if len(items) != 1 || items[0].PlanNumber != "P-2" {
		t.Fatalf("待办中应只剩未完成的 P-2：%+v", items)
	}
}

